for theme in ['light','dark']:
    spec=tokens['explanationBackground'];palette=spec[theme]
    output=ROOT/palette['asset'];output.parent.mkdir(parents=True,exist_ok=True)
    output.write_text(f'''<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1920" viewBox="0 0 1080 1920">
  <title>teruya.dev sketchbook grid - {theme}</title>
  <desc>Transparent static background, 216 px spacing, 1.5 px stroke. Composite behind explanation components.</desc>
  <defs><pattern id="sketchbook-{theme}" width="216" height="216" patternUnits="userSpaceOnUse">
    <path d="M216 0H0V216" fill="none" stroke="{palette['stroke']}" stroke-opacity="{palette['opacity']}" stroke-width="1.5"/>
  </pattern></defs>
  <rect width="1080" height="1920" fill="url(#sketchbook-{theme})"/>
</svg>\n''')

