catalog=json.loads((SOURCE/'gallery/api/library.json').read_text())
recipes=[]
for name,style,demo,original,adapt,checks in data:
    card=next(c for c in catalog['cards'] if c['name']==name)
    assert style in [s['key'] for s in card['styles']], (name,style)
    demo='demos/'+demo
    paths={'card':card['source'],'demo':demo}
    evidence={k:{'path':v,'url':URL+v,'sha256':hashlib.sha256((SOURCE/v).read_bytes()).hexdigest()} for k,v in paths.items()}
    recipes.append({'recipeId':name,'styleKey':style,'source':evidence,'originalReferenceFps':30,'original':original,'teruyaAdaptation':adapt,'validationChecks':checks,'implementation':{'engine':None,'nativeProject':None,'render':None},'validation':{'status':'pending','sourceFilesChecked':True,'referencePlaybackCompared':False,'verticalRenderReviewed':False}})
